mapper.sql:
where account_id=#{accountId} and usage_date between #{from} and #{to}
    and application_scope_id=#{applicationId}
    and capability=#{capability}

where c.account_id=#{accountId} and c.created_at >= #{from}
    and c.created_at < date_add(#{to},interval 1 day)
    and c.application_id=#{applicationId}
    and c.capability=#{capability}
    and c.status=#{status}

mapper.select:
select max_file_bytes as maxFileBytes,max_sessions as maxSessions,
    max_generation_tasks as maxGenerationTasks,max_turns as maxTurns,revision from p_account_limit
    where account_id=#{accountId}

mapper.update:
update p_quota_balance set granted_units=granted_units+#{units},
    revision=revision+1,updated_at=utc_timestamp(3)
    where account_id=#{accountId} and quota_type=#{quotaType}
      and granted_units <= 9223372036854775807-#{units}
